∀ {d : Nat} {Var : Type} [inst : DecidableEq Var] [inst_1 : NeZero d] (c : QProg Var d) (Δ : @CQState (@Store Var) d)
  (Ψ : @CQAssertion (@Store Var) d),
  @expect (@Store Var) d Δ (wp d Var inst inst_1 c Ψ) =
    @expect (@Store Var) d (QMonad.Q.toStateFun (@Store Var) d (interp Var inst d inst_1 c) Δ) Ψ

∀ {d : Nat} {Var : Type} [inst : DecidableEq Var] [inst_1 : NeZero d] {c : QProg Var d} {Δ : @CQState (@Store Var) d}
  {Ψ : @CQAssertion (@Store Var) d},
  @expect (@Store Var) d Δ (wp d Var inst inst_1 c Ψ) ≤
    @expect (@Store Var) d (QMonad.Q.toStateFun (@Store Var) d (interp Var inst d inst_1 c) Δ) Ψ
